IList<int> oneElementList = new List<int>() { 7 };
IList<int> intList = new List<int>() { 7, 10, 21, 30, 45, 50, 87 };

Console.WriteLine(oneElementList.Single());                    // 7
Console.WriteLine(intList.Single(i => i < 10));              // 7 (only one < 10)

// These throw exceptions:
// intList.Single()                    // multiple elements
// intList.Single(i => i < 100)        // multiple elements match
// emptyList.Single()                  // no elements

IList<int> oneElementList = new List<int>() { 7 };
IList<int> intList = new List<int>() { 7, 10, 21, 30, 45, 50, 87 };
IList<string> emptyList = new List<string>();

Console.WriteLine(oneElementList.SingleOrDefault());                    // 7
Console.WriteLine(emptyList.SingleOrDefault());                          // null
Console.WriteLine(intList.SingleOrDefault(i => i < 10));                // 7

// These throw exceptions:
// intList.SingleOrDefault(i => i < 100)  // multiple elements match
